set -eu
/bin/ash -n /etc/profile.d/90-appworker-limits.sh
/etc/init.d/sshd checkconfig
awk '
  $1 == "appworker" && $2 == "soft" && $3 == "nofile" && $4 == "8192" {sn=1}
  $1 == "appworker" && $2 == "hard" && $3 == "nofile" && $4 == "8192" {hn=1}
  $1 == "appworker" && $2 == "soft" && $3 == "nproc" && $4 == "256" {sp=1}
  $1 == "appworker" && $2 == "hard" && $3 == "nproc" && $4 == "256" {hp=1}
  END {exit !(sn && hn && sp && hp)}
' /etc/security/limits.d/90-appworker.conf
printf '%s\n' 'configuration validation: PASS'
printf 'sshd_before='; rc-service sshd status

